REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.account_programs,public.program_evidence,public.program_reminders FROM anon,authenticated;
REVOKE ALL ON public.account_programs,public.program_evidence,public.program_reminders FROM anon;
GRANT SELECT ON public.account_programs,public.program_evidence,public.program_reminders TO authenticated;
CREATE POLICY program_evidence_admin_only ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'sharing-evidence' OR NOT EXISTS(SELECT 1 FROM public.program_evidence e WHERE storage.objects.name=ANY(e.paths)) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY program_evidence_no_owner_delete ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'sharing-evidence' OR NOT EXISTS(SELECT 1 FROM public.program_evidence e WHERE storage.objects.name=ANY(e.paths)));
CREATE OR REPLACE FUNCTION public.request_own_bell_notice(_device uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE notice uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.push_devices WHERE id=_device AND user_id=auth.uid()) THEN RAISE EXCEPTION 'DEVICE_REQUIRED'; END IF; IF NOT public.can_notify(auth.uid()) THEN RAISE EXCEPTION 'NOTIFICATION_PREFERENCES'; END IF; INSERT INTO public.notifications(user_id,message) VALUES(auth.uid(),'గాయత్రి వన్ గంటను నొక్కి ఈ ఫోన్‌కు సూచన కోరారు · You requested a bell notification on this device') RETURNING id INTO notice; DELETE FROM public.push_deliveries WHERE notification_id=notice AND device_id<>_device; RETURN notice; END $$;
CREATE OR REPLACE FUNCTION public.send_referral_reminders() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.dispatch_program_requests() $$;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(auth.uid()) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; RETURN jsonb_build_object('goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date); END $$;
COMMENT ON FUNCTION public.send_referral_reminders() IS 'Legacy schedule now invokes the consented day10-13 bounded program; shared one-per-local-day ledger prevents duplicate dispatch.';